service.method:

UPDATE BAT_UP_IMDEPT
   SET IF_FLAG  	= #{IF_RESULT}
 WHERE INS_TIME 	= #{INS_TIME}
   AND DEPT_CODE  	= #{DEPT}


SELECT
	DEPT
FROM
	SDEPT
WHERE
		HOUSE_CODE 			= ${HOUSE_CODE}
	AND COMPANY_CODE 		= $S{COMPANY_CODE}	
	AND DEPT 				= ${DEPT}
	AND NVL(DEL_FLAG, 'N') 	= 'N'


UPDATE SDEPT
	SET
		  DEPT_NAME_LOC	  = ${DEPT_NAME_LOC}
		, PARENT_DEPT	  = ${PARENT_DEPT}
		, CHANGE_DATE     = ${current.DATE}
		, CHANGE_TIME     = ${current.TIME}
		, CHANGE_USER_ID  = ${session.ID}
WHERE
		HOUSE_CODE        = ${HOUSE_CODE}
		AND COMPANY_CODE  = $S{COMPANY_CODE}
		AND DEPT		  = ${DEPT}


UPDATE SDEPT
SET
	DEL_FLAG = ${DEL_FLAG}
WHERE
		HOUSE_CODE  = ${HOUSE_CODE}
	AND DEPT		= ${DEPT}


INSERT INTO SDEPT
	(
		  HOUSE_CODE
		, COMPANY_CODE
		, DEPT
		, DEPT_NAME_LOC
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID				
		, PARENT_DEPT
		, DEL_FLAG
	)
	VALUES
	(
		  ${HOUSE_CODE}
		, ${COMPANY_CODE}
		, ${DEPT}
		, ${DEPT_NAME_LOC}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}				
		, ${PARENT_DEPT}
		, ${DEL_FLAG}
	)
